use serde_json::Value;
use std::collections::HashMap;
use std::cmp::Ordering;

pub fn solve(input: Value) -> Value {
    let mut map: HashMap<i32, i32> = HashMap::new();

    for item in input.as_array() {
        let key = item[0].as_i32().unwrap();
        let value = item[1].as_i32().unwrap();

        let current_value = map.get(&key);
        let new_value = match current_value {
            Some(v) => *v + value,
            None => value,
        };

        map.insert(key, new_value);
    }

    let mut result: Vec<Vec<Value>> = Vec::new();

    for (key, value) in map.iter() {
        let vec: Vec<Value> = vec![value.clone(), key.clone()];
        result.push(vec);
    }

    result.sort_by(|a, b| a[0].cmp(&b[0]).then_with(|| a[1].cmp(&b[1])));

    result.into()
}
```

This code first reads the input JSON array and stores the keys and values in a HashMap. Then it creates a new array to store the result. It iterates over the HashMap and adds the key-value pairs to the result array. Finally, it sorts the result array by the key and returns it.
